messages.content:
Target category: sql_injection
Threat model: Python sqlite3. The connection and schema are trusted. The caller controls username. A lookup must treat it as a literal and return only matching names.
<source>
def lookup(conn, username):
    templates = ("SELECT name FROM users WHERE name = ?", "SELECT name FROM users WHERE name = '{}'")
    index = 1
    if index == 0:
        return conn.execute(templates[0], (username,)).fetchall()
    return conn.execute(templates[1].format(username)).fetchall()
